"use strict";
const $=id=>document.getElementById(id);
const t=(ru,en)=>$('language').value==='en'?en:ru;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const art='../stage-3/assets/';
const nick=()=>$('long').checked?'Искусствовед_Александра_из_Петербурга':t('Александра','Alexandra');
const states={};
function state(id,group,ru,en,note,check,task,draw,source='64:20204',contract=''){states[id]={id,group,ru,en,note,check,task,draw,source,contract};}
const btn=(ru,en,to,style='')=>`<button type="button" class="btn ${style}" data-to="${to}">${t(ru,en)}</button>`;
const action=(ru,en,name,style='')=>`<button type="button" class="btn ${style}" data-action="${name}">${t(ru,en)}</button>`;
const stack=(...items)=>`<div class="stack">${items.join('')}</div>`;
const tag=(ru,en,filled=false)=>`<span class="badge ${filled?'filled':''}">${t(ru,en)}</span>`;
const notice=(ru,en,error=false)=>`<div class="notice ${error?'error':''}" role="status">${t(ru,en)}</div>`;
const card=(title,body,cls='')=>`<section class="card ${cls}"><h3>${title}</h3>${body}</section>`;
const hero=(title,body)=>`<div class="hero"><img src="${art}figma_home_statue.png" alt=""><h3>${title}</h3><p>${body}</p></div>`;
const row=(title,sub,value='')=>`<div class="row"><div><strong>${title}</strong>${sub?`<small>${sub}</small>`:''}</div><span class="value">${value}</span></div>`;
const field=(ru,en,value='',type='text',extra='')=>`<label class="field">${t(ru,en)}<input type="${type}" value="${esc(value)}" ${extra}></label>`;
const choices=(multiple=false,disabled=false)=>[t('Дорический','Doric'),t('Ионический','Ionic'),t('Коринфский','Corinthian')].map((x,i)=>`<label class="choice"><input type="${multiple?'checkbox':'radio'}" name="answer" value="${i}" ${disabled?'disabled':''} ${i===1?'checked':''}><span>${x}</span></label>`).join('');
const para=(ru,en)=>`<p>${en===undefined||en===''?ru:t(ru,en)}</p>`;
const empty=(title,body)=>`<div class="empty-symbol" aria-hidden="true">○</div><h3>${title}</h3><p class="muted">${body}</p>`;
const divider='<div class="divider"></div>';
const course=()=>t('Искусство Древней Греции','Ancient Greek art');
const testTag=()=>tag('Тестовый курс · пример','Test course · example');
const topic=()=>tag('Тема 2 · Архитектура','Topic 2 · Architecture');
const dialog=(title,body,buttons)=>({body:current.startsWith('P')?card(t('Профиль','Profile'),row(esc(nick()),t('Публичный никнейм','Public nickname'))+row(t('Аккаунт','Account'),t('Настройки профиля','Profile settings'))):current.startsWith('A')?card(t('Вход','Sign in'),para('Email и пароль','Email and password')):current.startsWith('R')?card(t('Учебный прогресс','Learning progress'),para('Ваши достижения','Your achievements')):hero(course(),t('Тема 2 · Архитектура','Topic 2 · Architecture')),modal:`<h3>${title}</h3>${body}${stack(...buttons)}`});
