const ids=Object.keys(states);
let current='A01';
let previous='A02';
const history=[];
function go(id){if(!states[id])return;if(id!==current){history.push(current);previous=current;}location.hash=id;render();}
function nav(){return `<nav class="bottom-nav" aria-label="${t('Навигация приложения (макет)','App navigation (prototype)')}">`+[[t('Дом','Home'),'figma_nav_home.png','64:17399'],[t('Календарь','Calendar'),'figma_nav_calendar_glyph.png','64:19942'],[t('Уроки','Lessons'),'figma_nav_lessons_glyph.png','64:17234'],[t('Чат','Chat'),'figma_nav_chat_glyph.png','64:20092'],[t('Профиль','Profile'),'figma_profile_person.png','64:20204']].map(([title,img,node])=>`<button type="button" data-action="source" data-node="${node}"><img src="${art}${img}" alt=""><span>${title}</span></button>`).join('')+'</nav>';}
function drawIndex(){const query=$('search').value.toLowerCase();let group='';$('index').innerHTML=ids.filter(id=>`${id} ${states[id].ru} ${states[id].en}`.toLowerCase().includes(query)).map(id=>{const s=states[id];let out='';if(group!==s.group){group=s.group;out=`<h2>${group}</h2>`;}return out+`<a href="#${id}" ${id===current?'aria-current="page"':''}><span>${id}</span><span>${t(s.ru,s.en)}</span></a>`;}).join('');}
function render(){const id=location.hash.slice(1);if(states[id])current=id;const s=states[current];document.documentElement.lang=$('language').value;const content=s.draw();const body=typeof content==='string'?content:content.body;const modal=typeof content==='object'?content.modal:'';
 $('surface').innerHTML=`<header class="app-header"><button class="back" type="button" data-action="back" aria-label="${t('Назад','Back')}"><img src="${art}figma_back.png" alt=""></button><h2>${t(s.ru,s.en)}</h2><span></span></header><div class="app-scroll ${['P','T','A'].includes(current[0])?'art':''} ${modal?'modal-context':''}" ${modal?'inert':''}>${body}</div>${modal||current.startsWith('A')||['P05','P07'].includes(current)?'':nav()}${modal?`<div class="modal-shade"><section class="dialog" role="dialog" aria-modal="true" aria-label="${esc(t(s.ru,s.en))}">${modal}</section></div>`:''}`;
 $('state-id').textContent=`${current} · TASK ${s.task} · R1`;$('state-title').textContent=t(s.ru,s.en);$('state-note').textContent=s.note;$('state-check').textContent=s.check;$('state-source').textContent=`Figma Design ${s.source} + accepted Stage 3/4 references; Inter / #002854 / #6a93ce.`;$('state-contract').textContent=s.contract||'Preserve account/project ownership, receipt-safe saves, explicit online actions and native Back/IME. Examples simulate server states; actual success requires acknowledgement.';$('figma').href=`https://www.figma.com/design/gO7czKDJEPs8z3aG2YPlAE?node-id=${s.source.replace(':','-')}`;
 $('counter').textContent=`${ids.indexOf(current)+1} / ${ids.length}`;drawIndex();configure();updateCount();
 if(modal){queueMicrotask(()=>$('surface').querySelector('.dialog button')?.focus({preventScroll:true}));}
}
function configure(){$('device').style.setProperty('--width',`${$('width').value}px`);$('device').style.setProperty('--scale',Number($('preset').value)*Number($('system').value));$('device').classList.toggle('keyboard',$('ime').checked);$('ime-area').hidden=!$('ime').checked;}
function updateCount(){const input=$('answer-text');if(!input)return;const n=Array.from(input.value).length;$('text-count').textContent=`${n} / 2000`;input.setAttribute('aria-invalid',String(n>2000));input.setCustomValidity(n>2000?t('Максимум 2000 символов','Maximum 2000 characters'):'');$('surface').querySelectorAll('[data-to="Q15"]').forEach(b=>b.disabled=n>2000||!input.value.trim());}
function feedback(ru,en){const existing=$('prototype-feedback');existing?.remove();const el=document.createElement('div');el.id='prototype-feedback';el.className='notice';el.role='status';el.textContent=t(ru,en);($('surface').querySelector('.dialog')||$('surface').querySelector('.app-scroll')).append(el);el.scrollIntoView({block:'nearest'});}
document.addEventListener('click',e=>{const target=e.target.closest('[data-to],[data-action]');if(!target)return;if(target.dataset.to){go(target.dataset.to);return;}switch(target.dataset.action){
 case 'back':{const locked=['Q04','Q05','Q17'].includes(current)?'Q05':current==='M04'?'M04':['M03','M10'].includes(current)?'M10':['P12','P13'].includes(current)?'P13':null;const id=locked||history.pop()||previous;previous=current;location.hash=id;render();break;}
 case 'source-login': feedback('Здесь откроется существующий экран входа Figma 64:12164. Он не перерисовывается в этом ревью.','The existing Login frame 64:12164 opens here. It is not redesigned in this review.');break;
 case 'source':feedback(`Переход на существующий экран Figma ${target.dataset.node}. Его композиция сохраняется; макет не перерисовывает её.`,`Transition to existing Figma frame ${target.dataset.node}. Its composition is preserved, not redrawn in this prototype.`);break;
 case 'preview-one':$('preview-question').innerHTML=`<h3>${t('Какой ордер узнают по волютам капители?','Which order has volutes on its capital?')}</h3>${choices()}`;break;
 case 'preview-two':$('preview-question').innerHTML=`<h3>${t('Выберите ордеры с декоративной капителью','Select the orders with decorative capitals')}</h3>${choices(true)}`;break;
 case 'native-settings':feedback('В Android откроются системные настройки уведомлений. Здесь показана только точка перехода.','Android will open system notification settings. This prototype only marks that transition.');break;
 case 'native-network':feedback('В Android откроются настройки подключения. После возврата позиция останется на 24:18, видео — на паузе.','Android connection settings open here. On return, position stays at 24:18 and video stays paused.');break;
 case 'play':feedback('Симуляция: явное нажатие запускает видео с 24:18. Прототип не подключён к Mux.','Simulation: an explicit press starts playback at 24:18. This prototype is not connected to Mux.');break;
 case 'heart':target.textContent=target.textContent.includes('♡')?t('♥ Нравится','♥ Liked'):t('♡ Нравится','♡ Like');target.setAttribute('aria-pressed',String(target.textContent.includes('♥')));break;
 case 'grade':{const input=$('grade');if(!input.checkValidity()){input.reportValidity();return;}lastGrade=input.value;go('T18');break;}
 case 'grade-quiz':{const input=$('grade');if(!input.checkValidity()){input.reportValidity();return;}quizGrade=input.value;go('T24');break;}
 case 'return-text':if(!$('return-comment').value.trim()){feedback('Добавьте комментарий, который поможет доработать ответ.','Add feedback that helps the learner revise their answer.');$('return-comment').focus();}else go('T04');break;
 case 'save-question':if(!$('weight').checkValidity())$('weight').reportValidity();else go('T09');break;
 case 'reorder':{const c=$('surface').querySelector('.card');const rows=c.querySelectorAll('.row');c.insertBefore(rows[1],rows[0]);feedback('Порядок изменён в черновике. Публикация выполняется отдельно.','Draft order changed. Publication is a separate action.');break;}
 case 'add-question':go('T10');break;
 case 'delete':if(!$('delete-confirm').checked){feedback('Подтвердите, что понимаете последствия.','Confirm that you understand the consequences.');$('delete-confirm').focus();}else go('P12');break;
 case 'new-message':if(!$('message').value.trim()){feedback('Введите новое сообщение.','Write a new message.');}else go('M03');break;
 case 'practice':feedback('Тренировочный ответ проверен. XP: 0; первый результат дня остаётся прежним.','Practice answer checked. XP: 0; the first daily result is unchanged.');break;
 }});
document.addEventListener('input',e=>{if(e.target.id==='answer-text')updateCount();if(e.target.dataset.filter==='learners'){const q=e.target.value.toLowerCase();$('learners').querySelectorAll('.card').forEach(c=>c.hidden=!c.textContent.toLowerCase().includes(q));}});
document.addEventListener('change',e=>{if(e.target.id==='question-type'){$('author-options').querySelectorAll('input[name="key"]').forEach(input=>input.type=e.target.value==='single'?'radio':'checkbox');}if(e.target.id==='queue-filter'){$('queue-results').innerHTML=card(t('Фильтр применён','Filter applied'),para(t('Выбранный статус: ','Selected status: ')+esc(e.target.value),'')+btn('Открыть пример работы','Open example work','T05','secondary'));}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('surface').querySelector('.dialog')){e.preventDefault();go(previous);}if(e.key==='Tab'){const dialog=$('surface').querySelector('.dialog');if(!dialog)return;const focusable=[...dialog.querySelectorAll('button:not(:disabled),input,textarea,select,a[href]')];const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
['language','long'].forEach(id=>$(id).addEventListener('change',render));['preset','system','width','ime'].forEach(id=>$(id).addEventListener('change',configure));$('search').addEventListener('input',drawIndex);$('previous').onclick=()=>go(ids[(ids.indexOf(current)-1+ids.length)%ids.length]);$('next').onclick=()=>go(ids[(ids.indexOf(current)+1)%ids.length]);window.addEventListener('hashchange',render);
$('coverage-table').innerHTML='<table><thead><tr><th>Поверхность / Surface</th><th>Источник / Source</th><th>Task 2 treatment</th></tr></thead><tbody>'+sources.map(([name,id,scope])=>`<tr><td>${name}</td><td><a target="_blank" rel="noreferrer" href="https://www.figma.com/design/gO7czKDJEPs8z3aG2YPlAE?node-id=${id.replace(':','-')}">${id}</a></td><td>${scope}</td></tr>`).join('')+'</tbody></table>';
$('manifest').innerHTML='<table><thead><tr><th>ID</th><th>Новый экран / состояние</th><th>Task</th><th>Contract / transition</th></tr></thead><tbody>'+ids.map(id=>{const s=states[id];return `<tr><td><a href="#${id}">${id}</a></td><td>${s.ru}<br><small>${s.en}</small></td><td>${s.task}</td><td>${esc(s.contract||s.check)}</td></tr>`;}).join('')+'</tbody></table>';
window.review={states,ids,sources,go};render();
